interface.definition:
a!localVariables(
  local!getsubPosition: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3595917"(pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1,batchSize: -1)).data,
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: { "Task Filters" },
                    color: "STANDARD",
                    style: { "STRONG" }
                  )
                }
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(contents: {}),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: "Clear Filters",
                  link: #"SYSTEM_SYSRULES_dynamicLink"(
                    saveInto: {
                      if(
                        tointeger(ri!selectedTab) = 1,
                        null,
                        a!save(ri!assignees, null)
                      ),
                      a!save(ri!status, null),
                      a!save(ri!module, null),
                      a!save(ri!nameFilter, null),
                      a!save(ri!subPosition, null),
                      a!save(ri!fiscalYear, null)
                    }
                  ),
                  linkStyle: "STANDALONE"
                ),
                align: "RIGHT"
              )
            }
          )
        }
      ),
      #"SYSTEM_SYSRULES_columnsLayout"(
        showWhen: ri!selectedTab = 1,
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_pickerFieldCustom"(
              label: "First Name",
              selectedLabels: ri!nameFilter,
              placeholder: "Enter at least " & #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3895397" & " characters to search for a candidate",
              suggestFunction: #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12452683"(filter: _),
              value: ri!nameFilter,
              saveInto: { ri!nameFilter}
            )
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
              label: "Sub Position",
              placeholder: "Select a Sub Position",
              choiceLabels: index(local!getsubPosition, "subPosition", null),
              choiceValues: index(local!getsubPosition, "subPositionId", null),
              value: ri!subPosition,
              saveInto: { ri!subPosition }
            )
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
              label: "Fiscal Year",
              placeholder: "Select a Fiscal Year",
              choiceLabels: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6751857"(),
              choiceValues: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6751857"(),
              value: ri!fiscalYear,
              saveInto: { ri!fiscalYear }
            )
          )
        }
      ),
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              if(
                ri!selectedTab = 1,
                #"SYSTEM_SYSRULES_textField"(
                  label: "Assignee",
                  value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(ri!user),
                  readOnly: true
                ),
                #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
                  label: "Assignee",
                  placeholder: "Select an Assignee",
                  choiceLabels: if(
                    ri!selectedTab = 1,
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(ri!assigneeRefDataUnique),
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(ri!assigneeRefDataUnique)
                  ),
                  choiceValues: ri!assigneeRefDataUnique,
                  value: if(ri!selectedTab = 1, ri!user, ri!assignees),
                  saveInto: if(ri!selectedTab = 1, ri!user, ri!assignees),
                  disabled: if(ri!selectedTab = 1, true, false)
                )
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
                label: "Status",
                placeholder: "Select a Status",
                choiceLabels: ri!taskStatuses,
                choiceValues: ri!taskStatuses,
                value: ri!status,
                saveInto: ri!status
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
                label: "Module",
                placeholder: "Select a Module",
                choiceLabels: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3224774",
                choiceValues: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3224774",
                value: ri!module,
                saveInto: {ri!module,
                /*if(*/
                  /*ri!module= "ASK",*/
                  /*a!save(ri!nameFilter,null),*/
                  /*{}*/
                /*)*/

                },
              )
            }
          )
        }
      )
    },
    showWhen: ri!isShowFilters,
    style: "STANDARD",
    marginBelow: "STANDARD"
  )
)
